import { Command } from 'commander';
import ora from 'ora';
import { git, warnProtectedBranch } from '../utils/git.js';
import { generateCommitMessage } from '../ai/commitMessage.js';
import { addCommitNote } from '../utils/notes.js';

export function registerCommit(program: Command) {
  program
    .command('commit')
    .description('Create a git commit with AI assistance and notes')
    .option('-a, --all', 'Stage all changes')
    .option('--ai', 'Generate commit message with AI')
    .option('-s, --style <style>', 'AI style: conventional|casual|emoji', 'conventional')
    .option('-m, --message <msg>', 'Commit message')
    .option('--note <note>', 'Attach an annotated note stored locally')
    .action(async opts => {
      const gitClient = git();
      await warnProtectedBranch();
      if (opts.all) await gitClient.add('.');
      const spinner = ora('Preparing commit...').start();
      let message = opts.message as string;
      if (opts.ai || !message) {
        const diff = await gitClient.diff(['--cached']);
        message = await generateCommitMessage(diff, opts.style);
      }
      spinner.text = 'Creating commit...';
      const result = await gitClient.commit(message || 'chore: update');
      spinner.succeed(`Committed ${result.commit}`);
      if (opts.note) {
        addCommitNote(result.commit, opts.note);
        console.log('📝 Stored commit note.');
      }
    });
}
